using System.Text.Json;
namespace LeoLauncher;
sealed record MusicPlaylist(string Id,string Name,bool Pinned,List<MusicSong> Songs,string? QQId=null,string? QQName=null,DateTimeOffset? Synced=null,List<string>? HiddenIds=null,List<MusicSong>? ExtraSongs=null,int RemoteCount=0);
sealed class MusicLibrary
{
    readonly string? path;public string? Error{get;private set;}public List<MusicPlaylist> Items{get;private set;}=[];
    public MusicLibrary(string? file){path=file;if(file!=null&&File.Exists(file))try{Items=JsonSerializer.Deserialize<List<MusicPlaylist>>(File.ReadAllText(file))??[];if(Items.Any(p=>string.IsNullOrWhiteSpace(p.Id)||string.IsNullOrWhiteSpace(p.Name)||p.Songs==null||p.Songs.Any(s=>!QQMusic.Valid(s))||p.QQId!=null&&!QQPlaylists.ValidId(p.QQId))||Items.Select(p=>p.Id).Distinct().Count()!=Items.Count)throw new IOException("歌单文件损坏，已保留原文件");}catch{Items=[];Error="歌单文件无法读取，原文件已保留";}}
    void Save(List<MusicPlaylist> next){if(Error!=null)throw new IOException(Error);if(path!=null){File.WriteAllText(path+".tmp",JsonSerializer.Serialize(next));File.Move(path+".tmp",path,true);}Items=next;}
    public MusicPlaylist Create(string name){name=name.Trim();if(name.Length is <1 or >24)throw new ArgumentException("歌单名称请填写1到24个字");if(Items.Count>=30)throw new ArgumentException("最多保存30个歌单");var list=new MusicPlaylist(Guid.NewGuid().ToString("N"),name,true,[]);Save(Items.Append(list).ToList());return list;}
    public void Add(string id,MusicSong song){if(!QQMusic.Valid(song))throw new ArgumentException("歌曲无效");if(!Items.Any(p=>p.Id==id))throw new ArgumentException("歌单不存在");Save(Items.Select(p=>p.Id==id?p with{Songs=p.Songs.Append(song).DistinctBy(s=>s.Id).Take(200).ToList(),ExtraSongs=p.QQId==null?p.ExtraSongs:(p.ExtraSongs??[]).Append(song).DistinctBy(s=>s.Id).Take(200).ToList(),HiddenIds=p.HiddenIds?.Where(x=>x!=song.Id).ToList()}:p).ToList());}
    public MusicPlaylist Import(QQPlaylistData data,string? localName=null,string? targetId=null){if(!QQPlaylists.ValidId(data.Id)||data.Songs.Any(s=>!QQMusic.Valid(s)))throw new ArgumentException("无效的公开歌单");var old=targetId==null?Items.FirstOrDefault(p=>p.QQId==data.Id):Items.FirstOrDefault(p=>p.Id==targetId);if(targetId!=null&&old==null)throw new ArgumentException("歌单已删除，未保存同步结果");bool same=old?.QQId==data.Id;if(old==null&&Items.Count>=30)throw new ArgumentException("最多保存30个歌单");string name=old?.Name??localName??data.Name;if(name.Length>24)name=name[..24];var extras=same?old!.ExtraSongs??[]:old?.Songs??[];var hidden=same?old!.HiddenIds??[]:[];var merged=data.Songs.Where(s=>!hidden.Contains(s.Id)).Concat(extras).DistinctBy(s=>s.Id).Take(200).ToList();var next=new MusicPlaylist(old?.Id??Guid.NewGuid().ToString("N"),name,old?.Pinned??true,merged,data.Id,data.Name,DateTimeOffset.Now,hidden,extras,data.Total);Save(old==null?Items.Append(next).ToList():Items.Select(p=>p.Id==old.Id?next:p).ToList());return next;}
    public void Pin(string id)=>Save(Items.Select(p=>p.Id==id?p with{Pinned=!p.Pinned}:p).ToList());
    public void RemoveSong(string id,string song)=>Save(Items.Select(p=>p.Id==id?p with{Songs=p.Songs.Where(s=>s.Id!=song).ToList(),ExtraSongs=p.ExtraSongs?.Where(s=>s.Id!=song).ToList(),HiddenIds=p.QQId==null?p.HiddenIds:(p.HiddenIds??[]).Append(song).Distinct().ToList()}:p).ToList());
    public void Delete(string id)=>Save(Items.Where(p=>p.Id!=id).ToList());
}
static class MusicPrompt
{
    public static string? Name(IWin32Window owner){using var dialog=new BarcaWindow{Text="新建常听歌单",ClientSize=new Size(410,230),StartPosition=FormStartPosition.CenterParent};dialog.Controls.Add(BarcaUi.Chrome(dialog,"新建常听歌单","从搜索结果点击 ☆ 收歌，歌单留在本地。"));var text=new TextBox{Bounds=new Rectangle(24,111,360,32),MaxLength=24,BackColor=BarcaUi.Raised,ForeColor=BarcaUi.Text,BorderStyle=BorderStyle.FixedSingle,Font=BarcaUi.Font(11)};var ok=new BarcaButton{Text="创建并置顶",Bounds=new Rectangle(248,171,135,34)};ok.Click+=(_,_)=>{if(!string.IsNullOrWhiteSpace(text.Text))dialog.DialogResult=DialogResult.OK;};dialog.Controls.AddRange([text,ok]);dialog.AcceptButton=ok;dialog.Shown+=(_,_)=>text.Focus();return dialog.ShowDialog(owner)==DialogResult.OK?text.Text:null;}
}
